const { createCanvas, loadImage } = require('canvas');

async function addTextToImage(base64, text) {
  const img = await loadImage(`data:image/png;base64,${base64}`);
  const canvas = createCanvas(img.width, img.height);
  const ctx = canvas.getContext('2d');

  // Desenha a imagem original
  ctx.drawImage(img, 0, 0);

  // Ajuste de tamanho proporcional da fonte
  const fontSize = Math.floor(img.height * 0.1); // 12% da altura da imagem
  ctx.font = `bold ${fontSize}px Arial`;

  // Centralizar texto e melhorar contraste
  ctx.textAlign = 'center';
  ctx.textBaseline = 'bottom';

  // Cores e estilo
  ctx.lineWidth = Math.max(8, fontSize * 0.15); // borda proporcional (grossa)
  ctx.strokeStyle = 'black'; // contorno
  ctx.fillStyle = 'white'; // texto

  // Posição do texto — 50px acima do rodapé
  const x = img.width / 2;
  const y = img.height - fontSize * 0.3;

  // Desenha borda e preenchimento
  ctx.strokeText(text, x, y);
  ctx.fillText(text, x, y);

  return canvas.toDataURL().split(',')[1];
}

